import{_ as a,c as e,o as i,ag as t}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Maintenance and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"tweaks/index.md","filePath":"tweaks/index.md","lastUpdated":1792149212000}'),n={name:"tweaks/index.md"};function p(l,s,h,o,r,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="maintenance-and-recovery" tabindex="-1">Maintenance and recovery <a class="header-anchor" href="#maintenance-and-recovery" aria-label="Permalink to &quot;Maintenance and recovery&quot;">​</a></h1><p>Run commands as your regular user unless a section explicitly uses the live ISO or chroot.</p><h2 id="routine-maintenance" tabindex="-1">Routine maintenance <a class="header-anchor" href="#routine-maintenance" aria-label="Permalink to &quot;Routine maintenance&quot;">​</a></h2><p>Read <a href="https://archlinux.org/news/" target="_blank" rel="noreferrer">Arch Linux news</a> before upgrading, then perform a full system upgrade:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syu</span></span></code></pre></div><p>If you use AUR packages, also review and apply their updates with your helper, rebuilding packages affected by library changes. Restart affected applications and services; reboot after kernel updates to use the new kernel.</p><p>Review <code>.pacnew</code> and <code>.pacsave</code> files using <code>pacdiff</code> from <code>pacman-contrib</code>. Merge changes deliberately rather than overwriting your configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacdiff</span></span></code></pre></div><p><code>pacdiff</code> defaults to <code>vimdiff</code>; install <code>vim</code> or set <code>DIFFPROG</code> to an installed diff editor you know how to use.</p><p>Inspect orphaned and foreign packages periodically:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qdt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qm</span></span></code></pre></div><p>Review each candidate before removing it. An orphan may still be useful to you. See <a href="https://wiki.archlinux.org/title/System_maintenance" target="_blank" rel="noreferrer">System maintenance</a> and <a href="/post-installation/#package-cache-and-regular-updates">package cache cleanup</a>.</p><h2 id="memory-and-swap" tabindex="-1">Memory and swap <a class="header-anchor" href="#memory-and-swap" aria-label="Permalink to &quot;Memory and swap&quot;">​</a></h2><p>Keep the default swappiness until you have measured a problem. Swappiness controls the relative cost of swapping versus filesystem paging; it is not a percentage of RAM usage at which swapping starts. See the <a href="https://docs.kernel.org/admin-guide/sysctl/vm.html#swappiness" target="_blank" rel="noreferrer">kernel documentation</a>.</p><p>For compressed swap in RAM, install <code>zram-generator</code> and create <code>/etc/systemd/zram-generator.conf</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zram-generator</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/zram-generator.conf</span></span></code></pre></div><p>A simple configuration is:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[zram0]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">zram-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = min(ram / 2, 4096)</span></span></code></pre></div><p>Reboot to activate it, then check <code>zramctl</code> and <code>swapon --show</code>. This allocates a compressed swap device up to half of RAM, capped at 4 GiB. Zram cannot store a hibernation image; hibernation needs disk-backed swap and resume configuration. See <a href="https://wiki.archlinux.org/title/Zram" target="_blank" rel="noreferrer">Zram</a>.</p><p>If the desktop becomes unresponsive under memory pressure, consider <code>earlyoom</code> after checking which OOM policy is already active. Do not stack multiple OOM daemons without understanding their interaction. To choose earlyoom:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> earlyoom</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> earlyoom.service</span></span></code></pre></div><p>It can terminate applications with unsaved work; review its configuration for your workload.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><h3 id="personal-files" tabindex="-1">Personal files <a class="header-anchor" href="#personal-files" aria-label="Permalink to &quot;Personal files&quot;">​</a></h3><p>Back up personal files to another device or remote storage and test restoring them. Déjà Dup is one option:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deja-dup</span></span></code></pre></div><p>Include documents, saves, credentials and application data you need. <code>.config</code> and <code>.local/share</code> often contain important state; do not exclude them wholesale. Caches can usually be excluded. A synchronized folder is not by itself a versioned backup.</p><p>Encryption of your system disk does not encrypt a backup stored elsewhere. Configure encryption on the backup destination when it contains private data.</p><h3 id="system-snapshots" tabindex="-1">System snapshots <a class="header-anchor" href="#system-snapshots" aria-label="Permalink to &quot;System snapshots&quot;">​</a></h3><p><a href="https://github.com/linuxmint/timeshift" target="_blank" rel="noreferrer">Timeshift</a> can create rsync snapshots of the ext4 system used here:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timeshift</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cronie</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cronie.service</span></span></code></pre></div><p>Configure the destination and schedule in Timeshift. Its Btrfs mode requires a supported subvolume layout; it is not applicable to this ext4 installation. Timeshift excludes user data by default and is not a substitute for a separate personal backup.</p><p>Upstream supports GRUB2 for bootloader restoration. With systemd-boot, plan to restore the ESP and boot entries separately using the recovery procedure below. Keep a separate backup of <code>/boot</code>, <code>/etc</code> and, for encryption, the <a href="/encryption/#header-backup-and-ssd-discard">LUKS header</a>.</p><h3 id="package-and-service-lists" tabindex="-1">Package and service lists <a class="header-anchor" href="#package-and-service-lists" aria-label="Permalink to &quot;Package and service lists&quot;">​</a></h3><p>Record explicitly installed repository and foreign packages separately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qqen</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages-official.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qqem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages-foreign.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-unit-files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --state=enabled</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enabled-services.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-unit-files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --state=enabled</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enabled-user-services.txt</span></span></code></pre></div><p>Save these with your backups. After reinstalling and fully upgrading, restore available official packages with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --needed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages-official.txt</span></span></code></pre></div><p>Review foreign packages individually and rebuild them from trusted sources. Package names and availability may have changed. Re-enable needed services deliberately, distinguishing system services from user services.</p><h2 id="recover-from-the-installation-iso" tabindex="-1">Recover from the installation ISO <a class="header-anchor" href="#recover-from-the-installation-iso" aria-label="Permalink to &quot;Recover from the installation ISO&quot;">​</a></h2><p>Boot a current ISO in the same firmware mode, connect to the internet and identify the devices with <code>lsblk -f</code>. Run the following as root in the live ISO, substituting your actual partitions.</p><p>For the unencrypted example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt</span></span></code></pre></div><p>For the encrypted example, use these commands instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cryptsetup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cryptroot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vgchange</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/mapper/main-root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt</span></span></code></pre></div><p>On UEFI, mount the ESP before entering the system. Also mount any separate filesystems needed for the repair:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/boot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arch-chroot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt</span></span></code></pre></div><p>On BIOS, skip the ESP mount and run <code>arch-chroot /mnt</code> directly. Inspect the error and configuration before changing packages. If an upgrade was interrupted, complete a full <code>pacman -Syu</code>; reinstall affected packages if necessary.</p><p>After fixing initramfs configuration or reinstalling kernel packages:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkinitcpio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span></span></code></pre></div><p>For GRUB, regenerate <code>/boot/grub/grub.cfg</code> with <code>grub-mkconfig -o /boot/grub/grub.cfg</code>. If its boot files need reinstalling, repeat the appropriate <a href="/installation/install-bootloader#grub">GRUB installation</a> command first.</p><p>For systemd-boot, use <code>bootctl --esp-path=/boot install</code> if the boot manager needs reinstalling. Restore or recreate the loader entries and verify their kernel paths and root/encryption options. If the ESP was lost, reinstall the kernel packages while it is mounted, then regenerate the initramfs; reinstalling the boot manager alone does not restore kernels.</p><p>Exit the chroot, unmount with <code>umount -R /mnt</code>, then reboot. Keep the ISO available until you have verified a successful boot.</p>`,53)])])}const g=a(n,[["render",p]]);export{k as __pageData,g as default};
